import express from 'express';

let nextId = 2;
const menu = [{ id: 1, nama: 'Kopi Susu', harga: 18000 }];
const app = express();
app.use(express.json());

app.post('/menu', (req, res) => {
  const { nama, harga } = req.body;
  if (typeof nama !== 'string' || typeof harga !== 'number') {
    return res.status(400).json({ error: 'nama (teks) dan harga (angka) wajib' });
  }
  const baru = { id: nextId++, nama, harga };
  menu.push(baru);
  res.status(201).json(baru);
});
app.patch('/menu/:id', (req, res) => {
  const m = menu.find((x) => x.id === Number(req.params.id));
  if (!m) return res.status(404).json({ error: 'Menu tidak ada' });
  if (req.body.harga !== undefined) m.harga = req.body.harga;
  res.json(m);
});
app.delete('/menu/:id', (req, res) => {
  const i = menu.findIndex((x) => x.id === Number(req.params.id));
  if (i === -1) return res.status(404).json({ error: 'Menu tidak ada' });
  menu.splice(i, 1);
  res.sendStatus(204);
});
const server = app.listen(3000);

const kirim = (method, jalur, body) => fetch('http://localhost:3000' + jalur, {
  method, headers: { 'Content-Type': 'application/json' }, body: body && JSON.stringify(body),
});
let r = await kirim('POST', '/menu', { nama: 'Teh Tarik', harga: 12000, gratis: true });
console.log(r.status, await r.json());
r = await kirim('PATCH', '/menu/1', { harga: 20000 });
console.log(r.status, (await r.json()).harga);
r = await kirim('DELETE', '/menu/2');
console.log(r.status, menu.length);
server.close();

