import express from 'express';
const data = [];
const app = express();
app.use(express.json());
app.post('/angka', (req, res) => {
  data.push(req.body.nilai);
  res.status(201).json({ total: data.reduce((a, b) => a + b, 0) });
});
const server = app.listen(3000);
let d;
for (const nilai of [5, 7]) {
  const r = await fetch('http://localhost:3000/angka', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ nilai }) });
  d = await r.json();
}
console.log(d.total);
server.close();
